1	"use client";
2	
3	import { useState, useEffect } from "react";
4	import { supabase } from "@/integrations/supabase/client";
5	import { Button } from "@/components/ui/button";
6	import { Input } from "@/components/ui/input";
7	import { Label } from "@/components/ui/label";
8	import { Badge } from "@/components/ui/badge";
9	import { Switch } from "@/components/ui/switch";
10	import { Skeleton } from "@/components/ui/skeleton";
11	import {
12	  Select,
13	  SelectContent,
14	  SelectItem,
15	  SelectTrigger,
16	  SelectValue,
17	} from "@/components/ui/select";
18	import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
19	import { toast } from "sonner";
20	import {
21	  ChevronDown,
22	  Plus,
23	  Trash2,
24	  ChevronUp,
25	  Loader2,
26	  GripVertical,
27	  FormInput,
28	  X,
29	} from "lucide-react";
30	
31	type FieldType =
32	  | "text"
33	  | "number"
34	  | "select"
35	  | "multiselect"
36	  | "date"
37	  | "url"
38	  | "textarea"
39	  | "checkbox";
40	
41	interface FormField {
42	  id: string;
43	  job_id: string;
44	  field_type: FieldType;
45	  label: string;
46	  placeholder: string | null;
47	  required: boolean;
48	  options: string[] | null;
49	  sort_order: number;
50	  is_knockout: boolean;
51	  knockout_answer: string | null;
52	  created_at: string;
53	}
54	
55	const FIELD_TYPE_LABELS: Record<FieldType, string> = {
56	  text: "Text",
57	  number: "Number",
58	  select: "Dropdown",
59	  multiselect: "Multi-select",
60	  date: "Date",
61	  url: "URL",
62	  textarea: "Long Text",
63	  checkbox: "Checkbox",
64	};
65	
66	const FIELD_TYPES_WITH_OPTIONS: FieldType[] = ["select", "multiselect"];
67	
68	interface AddFieldFormState {
69	  field_type: FieldType;
70	  label: string;
71	  placeholder: string;
72	  required: boolean;
73	  options: string;
74	  is_knockout: boolean;
75	  knockout_answer: string;
76	}
77	
78	const DEFAULT_ADD_STATE: AddFieldFormState = {
79	  field_type: "text",
80	  label: "",
81	  placeholder: "",
82	  required: false,
83	  options: "",
84	  is_knockout: false,
85	  knockout_answer: "",
86	};
87	
88	interface FormBuilderProps {
89	  jobId: string;
90	}
91	
92	export default function FormBuilder({ jobId }: FormBuilderProps) {
93	  const [open, setOpen] = useState(false);
94	  const [fields, setFields] = useState<FormField[]>([]);
95	  const [loading, setLoading] = useState(false);
96	  const [loaded, setLoaded] = useState(false);
97	  const [showAddForm, setShowAddForm] = useState(false);
98	  const [addState, setAddState] = useState<AddFieldFormState>(DEFAULT_ADD_STATE);
99	  const [saving, setSaving] = useState(false);
100	  const [deletingId, setDeletingId] = useState<string | null>(null);
101	  const [movingId, setMovingId] = useState<string | null>(null);
102	  const [editingId, setEditingId] = useState<string | null>(null);
103	  const [editState, setEditState] = useState<AddFieldFormState>(DEFAULT_ADD_STATE);
104	
105	  useEffect(() => {
106	    if (!open || loaded) return;
107	    setLoading(true);
108	    (supabase as any)
109	      .from("job_form_fields")
110	      .select("*")
111	      .eq("job_id", jobId)
112	      .order("sort_order", { ascending: true })
113	      .then(({ data, error }: { data: FormField[] | null; error: any }) => {
114	        setLoading(false);
115	        if (error) {
116	          toast.error("Failed to load form fields");
117	          return;
118	        }
119	        setFields(data ?? []);
120	        setLoaded(true);
121	      });
122	  }, [open, jobId, loaded]);
123	
124	  const handleAdd = async () => {
125	    if (!addState.label.trim()) {
126	      toast.error("Label is required");
127	      return;
128	    }
129	    if (
130	      FIELD_TYPES_WITH_OPTIONS.includes(addState.field_type) &&
131	      !addState.options.trim()
132	    ) {
133	      toast.error("Options are required for dropdown/multi-select fields");
134	      return;
135	    }
136	    if (addState.is_knockout && !addState.knockout_answer.trim()) {
137	      toast.error("Knockout answer is required when knockout is enabled");
138	      return;
139	    }
140	
141	    setSaving(true);
142	    try {
143	      const optionsArray = FIELD_TYPES_WITH_OPTIONS.includes(addState.field_type)
144	        ? addState.options
145	            .split(",")
146	            .map((o) => o.trim())
147	            .filter(Boolean)
148	        : null;
149	
150	      const newOrder =
151	        fields.length > 0 ? Math.max(...fields.map((f) => f.sort_order)) + 1 : 0;
152	
153	      const payload = {
154	        job_id: jobId,
155	        field_type: addState.field_type,
156	        label: addState.label.trim(),
157	        placeholder: addState.placeholder.trim() || null,
158	        required: addState.required,
159	        options: optionsArray,
160	        sort_order: newOrder,
161	        is_knockout: addState.is_knockout,
162	        knockout_answer: addState.is_knockout ? addState.knockout_answer.trim() || null : null,
