472	interface FieldFormProps {
473	  state: AddFieldFormState;
474	  onChange: (s: AddFieldFormState) => void;
475	  onSave: () => void;
476	  onCancel: () => void;
477	  saving: boolean;
478	  mode: "add" | "edit";
479	}
480	
481	function FieldForm({ state, onChange, onSave, onCancel, saving, mode }: FieldFormProps) {
482	  const needsOptions = FIELD_TYPES_WITH_OPTIONS.includes(state.field_type);
483	
484	  const set = (key: keyof AddFieldFormState, value: string | boolean) =>
485	    onChange({ ...state, [key]: value });
486	
487	  return (
488	    <div className="space-y-3">
489	      {/* Row 1: type + label */}
490	      <div className="grid grid-cols-2 gap-2">
491	        <div className="space-y-1">
492	          <Label className="text-xs">Field Type</Label>
493	          <Select
494	            value={state.field_type}
495	            onValueChange={(v) => set("field_type", v as FieldType)}
496	          >
497	            <SelectTrigger className="h-8 text-xs">
498	              <SelectValue />
499	            </SelectTrigger>
500	            <SelectContent>
501	              {(Object.keys(FIELD_TYPE_LABELS) as FieldType[]).map((t) => (
502	                <SelectItem key={t} value={t} className="text-xs">
503	                  {FIELD_TYPE_LABELS[t]}
504	                </SelectItem>
505	              ))}
506	            </SelectContent>
507	          </Select>
508	        </div>
509	        <div className="space-y-1">
510	          <Label className="text-xs">Label *</Label>
511	          <Input
512	            value={state.label}
513	            onChange={(e) => set("label", e.target.value)}
514	            placeholder="e.g. Years of experience"
515	            className="h-8 text-xs"
516	          />
517	        </div>
518	      </div>
519	
520	      {/* Placeholder */}
521	      <div className="space-y-1">
522	        <Label className="text-xs">Placeholder</Label>
523	        <Input
524	          value={state.placeholder}
525	          onChange={(e) => set("placeholder", e.target.value)}
526	          placeholder="Optional helper text shown inside the field"
527	          className="h-8 text-xs"
528	        />
529	      </div>
530	
531	      {/* Options for select/multiselect */}
532	      {needsOptions && (
533	        <div className="space-y-1">
534	          <Label className="text-xs">Options * (comma-separated)</Label>
535	          <Input
536	            value={state.options}
537	            onChange={(e) => set("options", e.target.value)}
538	            placeholder="e.g. 0-1 years, 1-3 years, 3-5 years, 5+ years"
539	            className="h-8 text-xs"
540	          />
541	        </div>
542	      )}
543	
544	      {/* Required toggle */}
545	      <div className="flex items-center gap-2">
546	        <Switch
547	          id={`req-${mode}`}
548	          checked={state.required}
549	          onCheckedChange={(v) => set("required", v)}
550	          className="scale-75"
551	        />
552	        <Label htmlFor={`req-${mode}`} className="text-xs cursor-pointer">
553	          Required field
554	        </Label>
555	      </div>
556	
557	      {/* Knockout toggle */}
558	      <div className="flex items-center gap-2">
559	        <Switch
560	          id={`ko-${mode}`}
561	          checked={state.is_knockout}
562	          onCheckedChange={(v) => set("is_knockout", v)}
563	          className="scale-75"
564	        />
565	        <Label htmlFor={`ko-${mode}`} className="text-xs cursor-pointer">
566	          Knockout question (auto-disqualify if answer matches)
567	        </Label>
568	      </div>
569	
570	      {/* Knockout answer */}
571	      {state.is_knockout && (
572	        <div className="space-y-1">
573	          <Label className="text-xs">
574	            Disqualify when answer equals *
575	          </Label>
576	          <Input
577	            value={state.knockout_answer}
578	            onChange={(e) => set("knockout_answer", e.target.value)}
579	            placeholder="e.g. No"
580	            className="h-8 text-xs border-red-300 dark:border-red-700"
581	          />
582	          <p className="text-[10px] text-muted-foreground">
583	            Applicant will be auto-rejected if their response exactly matches this value.
584	          </p>
585	        </div>
586	      )}
587	
588	      {/* Actions */}
589	      <div className="flex items-center gap-2 pt-1">
590	        <Button
591	          size="sm"
592	          className="h-7 text-xs gap-1"
593	          onClick={onSave}
594	          disabled={saving}
595	        >
596	          {saving ? <Loader2 className="h-3 w-3 animate-spin" /> : null}
597	          {mode === "add" ? "Add Field" : "Save Changes"}
598	        </Button>
599	        <Button
600	          variant="ghost"
601	          size="sm"
602	          className="h-7 text-xs gap-1"
603	          onClick={onCancel}
604	          disabled={saving}
605	        >
606	          <X className="h-3 w-3" />
607	          Cancel
608	        </Button>
609	      </div>
610	    </div>
611	  );
612	}
