4	// Public endpoint — allow all origins so the hosted apply page can POST
5	const corsHeaders = {
6	  "Access-Control-Allow-Origin": "*",
7	  "Access-Control-Allow-Headers":
8	    "authorization, x-client-info, apikey, content-type",
9	  "Access-Control-Allow-Methods": "POST, OPTIONS",
