16	// ── Simple in-memory rate limiter ──────────────────────────
17	const ipBuckets = new Map<string, { count: number; resetAt: number }>();
18	const jobBuckets = new Map<string, { count: number; resetAt: number }>();
19	
20	function isRateLimited(ip: string, jobId: string): string | null {
21	  const now = Date.now();
22	  const ipEntry = ipBuckets.get(ip);
23	  if (ipEntry && now < ipEntry.resetAt) {
24	    if (ipEntry.count >= 5) return "Too many submissions. Please try again later.";
25	    ipEntry.count++;
26	  } else {
27	    ipBuckets.set(ip, { count: 1, resetAt: now + 60_000 });
28	  }
29	  const jobEntry = jobBuckets.get(jobId);
30	  if (jobEntry && now < jobEntry.resetAt) {
31	    if (jobEntry.count >= 100) return "This position has received too many applications right now.";
32	    jobEntry.count++;
33	  } else {
34	    jobBuckets.set(jobId, { count: 1, resetAt: now + 3_600_000 });
35	  }
36	  if (ipBuckets.size > 1000) {
37	    for (const [k, v] of ipBuckets) { if (now >= v.resetAt) ipBuckets.delete(k); }
38	  }
39	  return null;
40	}
