42	const MAX_RESUME_BYTES = 10 * 1024 * 1024; // 10 MB
43	const ALLOWED_MIME = [
44	  "application/pdf",
45	  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
46	  "application/msword",
47	  "text/plain",
48	  "application/rtf",
49	  "text/rtf",
50	];
51	const ALLOWED_EXTENSIONS = [".pdf", ".docx", ".doc", ".rtf", ".txt"];
