105	      email = (form.get("email") as string | null)?.trim() ?? "";
106	      phone = (form.get("phone") as string | null)?.trim() || null;
107	      linkedinUrl = (form.get("linkedin_url") as string | null)?.trim() || null;
108	      const fileEntry = form.get("resume");
109	      if (fileEntry instanceof File && fileEntry.size > 0) {
