122	      const body = await req.json();
123	      jobId = body.job_id?.trim() ?? "";
124	      name = body.name?.trim() ?? "";
125	      email = body.email?.trim() ?? "";
126	      phone = body.phone?.trim() || null;
127	      linkedinUrl = body.linkedin_url?.trim() || null;
128	      if (body.custom_fields && typeof body.custom_fields === "object") {
