144	      }
145	    }
146	
147	    // ── Validation ────────────────────────────────────────────────────────
148	    const errors: string[] = [];
149	    if (!jobId) errors.push("job_id is required");
150	    if (!name) errors.push("name is required");
151	    if (!email) errors.push("email is required");
